    createSession: (code: string, psu?: PsuContext) => call(sessionSchema, "POST", "/sessions", { body: { code }, psu }),
    deleteSession: (sessionId: string, psu?: PsuContext) => call(z.unknown(), "DELETE", `/sessions/${encodeURIComponent(sessionId)}`, { psu }),
